-- Online DATE -> TIMESTAMP WITH TIME ZONE. A direct ALTER TABLE ... MODIFY is
-- rejected with ORA-01439 (column must be empty to change datatype) regardless of
-- table size, so redefinition is required rather than merely faster.
BEGIN DBMS_REDEFINITION.CAN_REDEF_TABLE('APP', 'ORDERS',
        DBMS_REDEFINITION.CONS_USE_PK); END;
/
CREATE TABLE orders_interim (
  id NUMBER, user_id NUMBER, amount NUMBER(12,2),
  created_at TIMESTAMP WITH TIME ZONE);
BEGIN
  DBMS_REDEFINITION.START_REDEF_TABLE('APP','ORDERS','ORDERS_INTERIM',
    'id id, user_id user_id, amount amount, CAST(created_at AS TIMESTAMP WITH TIME ZONE) created_at',
    options_flag => DBMS_REDEFINITION.CONS_USE_PK);
END;
/
DECLARE
  num_errors PLS_INTEGER;
BEGIN
  DBMS_REDEFINITION.COPY_TABLE_DEPENDENTS('APP','ORDERS','ORDERS_INTERIM',
    ignore_errors => FALSE, num_errors => num_errors);
  IF num_errors > 0 THEN
    RAISE_APPLICATION_ERROR(-20001,
      'COPY_TABLE_DEPENDENTS reported errors; see DBA_REDEFINITION_ERRORS');
  END IF;
END;
/
BEGIN DBMS_REDEFINITION.SYNC_INTERIM_TABLE('APP','ORDERS','ORDERS_INTERIM'); END;
/
BEGIN
  DBMS_REDEFINITION.FINISH_REDEF_TABLE('APP','ORDERS','ORDERS_INTERIM',
    dml_lock_timeout => 30);
END;
/
